/**
 * @file Admin Users API
 * GET — list all users
 * POST — create new user
 * PUT — update user
 * DELETE — delete user
 * All methods require admin role.
 */

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';
import { hashPassword, requireAdmin, ROLE_TO_DUSUN_NAME } from '@/lib/auth';
import { VALID_ROLES } from '@/lib/requestValidation';
import { writeLog } from '@/lib/audit';

const MIN_PASSWORD_LENGTH = 12;
const USERNAME_PATTERN = /^[a-zA-Z0-9_.-]{3,32}$/;

function validateUsername(username) {
  const value = String(username || '').trim();
  if (!USERNAME_PATTERN.test(value)) {
    return { error: 'Username harus 3-32 karakter dan hanya boleh huruf, angka, titik, underscore, atau strip' };
  }
  return { value };
}

function validateFullName(name) {
  const value = String(name || '').trim();
  if (value.length < 2 || value.length > 100) {
    return { error: 'Nama lengkap harus 2-100 karakter' };
  }
  return { value };
}

function validatePassword(password, { required = true } = {}) {
  if (!password && !required) return { value: null };
  const value = String(password || '');
  if (value.length < MIN_PASSWORD_LENGTH) {
    return { error: `Password minimal ${MIN_PASSWORD_LENGTH} karakter` };
  }
  return { value };
}

async function getAdminCount() {
  const { count, error } = await supabase
    .from('users')
    .select('id', { count: 'exact', head: true })
    .eq('role', 'admin');
  if (error) throw error;
  return count || 0;
}

/**
 * Resolve `dusun_id` untuk role kader-dusun.
 * - Kalau role bukan kader-dusun → return null (kolom users.dusun_id di-set NULL)
 * - Kalau role kader-dusun → cari dusun_id dari nama dusun via ROLE_TO_DUSUN_NAME mapping
 *   Kalau dusun tidak ditemukan di DB, return error.
 */
async function resolveDusunIdForRole(role) {
  const dusunNama = ROLE_TO_DUSUN_NAME[role];
  if (!dusunNama) return { value: null };
  const { data } = await supabase
    .from('dusun')
    .select('id')
    .eq('nama', dusunNama)
    .eq('is_active', 1)
    .maybeSingle();
  if (!data) {
    return { error: `Dusun "${dusunNama}" tidak ditemukan di database. Pastikan migration v5 sudah dijalankan.` };
  }
  return { value: data.id };
}

export async function GET(request) {
  try {
    const admin = await requireAdmin(request);
    if (!admin || admin.__forbidden) return requireAdmin.deny(admin);

    const { data: users, error } = await supabase
      .from('users')
      .select('id, username, nama_lengkap, role, dusun_id, created_at')
      .order('id');

    if (error) throw error;
    return NextResponse.json(users);
  } catch (error) {
    return NextResponse.json({ error: 'Gagal mengambil data' }, { status: 500 });
  }
}

export async function POST(request) {
  try {
    const admin = await requireAdmin(request);
    if (!admin || admin.__forbidden) return requireAdmin.deny(admin);

    const { username, password, nama_lengkap, role } = await request.json();

    if (!username || !password || !nama_lengkap) {
      return NextResponse.json({ error: 'Semua field harus diisi' }, { status: 400 });
    }
    const validUsername = validateUsername(username);
    if (validUsername.error) return NextResponse.json({ error: validUsername.error }, { status: 400 });

    const validName = validateFullName(nama_lengkap);
    if (validName.error) return NextResponse.json({ error: validName.error }, { status: 400 });

    const validPassword = validatePassword(password);
    if (validPassword.error) return NextResponse.json({ error: validPassword.error }, { status: 400 });

    const nextRole = role || 'user';
    if (!VALID_ROLES.has(nextRole)) {
      return NextResponse.json({ error: 'Role tidak valid' }, { status: 400 });
    }

    const { data: existing } = await supabase.from('users').select('id').eq('username', validUsername.value).single();
    if (existing) {
      return NextResponse.json({ error: 'Username sudah digunakan' }, { status: 409 });
    }

    const password_hash = await hashPassword(validPassword.value);

    // Auto-resolve dusun_id untuk role kader-dusun
    const dusunResolve = await resolveDusunIdForRole(nextRole);
    if (dusunResolve.error) {
      return NextResponse.json({ error: dusunResolve.error }, { status: 400 });
    }

    const { error } = await supabase
      .from('users')
      .insert({
        username: validUsername.value,
        password_hash,
        nama_lengkap: validName.value,
        role: nextRole,
        dusun_id: dusunResolve.value,
      });

    if (error) throw error;

    await writeLog({
      userId: admin.userId,
      username: admin.username,
      action: 'create_user',
      tableName: 'users',
      detail: `Membuat pengguna baru "${validUsername.value}" (role: ${nextRole})`,
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('[Admin Users POST Error]:', error);
    return NextResponse.json({ error: 'Gagal menambahkan pengguna' }, { status: 500 });
  }
}

export async function DELETE(request) {
  try {
    const admin = await requireAdmin(request);
    if (!admin || admin.__forbidden) return requireAdmin.deny(admin);

    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return NextResponse.json({ error: 'ID harus diisi' }, { status: 400 });
    }

    const targetId = Number(id);
    if (!Number.isInteger(targetId) || targetId < 1) {
      return NextResponse.json({ error: 'ID tidak valid' }, { status: 400 });
    }
    if (targetId === admin.userId) {
      return NextResponse.json({ error: 'Admin tidak dapat menghapus akun yang sedang digunakan' }, { status: 400 });
    }

    const { data: targetUser, error: targetError } = await supabase
      .from('users')
      .select('id, username, role')
      .eq('id', targetId)
      .single();
    if (targetError || !targetUser) {
      return NextResponse.json({ error: 'Pengguna tidak ditemukan' }, { status: 404 });
    }
    if (targetUser.username === 'admin') {
      return NextResponse.json({ error: 'Akun admin bawaan tidak dapat dihapus' }, { status: 400 });
    }
    const adminCount = await getAdminCount();
    if (targetUser.role === 'admin' && adminCount <= 1) {
      return NextResponse.json({ error: 'Minimal harus ada satu admin aktif' }, { status: 400 });
    }

    // Hindari error foreign key dengan mengosongkan relasi foreign key
    await supabase.from('audit_logs').update({ user_id: null }).eq('user_id', targetId);
    await supabase.from('report_periods').update({ submitted_by: null }).eq('submitted_by', targetId);
    await supabase.from('report_periods').update({ approved_by: null }).eq('approved_by', targetId);
    await supabase.from('notifications').update({ user_id: null }).eq('user_id', targetId);

    const { error } = await supabase
      .from('users')
      .delete()
      .eq('id', targetId);

    if (error) throw error;

    await writeLog({
      userId: admin.userId,
      username: admin.username,
      action: 'delete_user',
      tableName: 'users',
      detail: `Menghapus pengguna "${targetUser.username}" (role: ${targetUser.role})`,
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('[Admin Users DELETE Error]:', error);
    return NextResponse.json({ error: 'Gagal menghapus pengguna' }, { status: 500 });
  }
}

export async function PUT(request) {
  try {
    const admin = await requireAdmin(request);
    if (!admin || admin.__forbidden) return requireAdmin.deny(admin);

    const { id, role, nama_lengkap, password } = await request.json();
    if (!id) return NextResponse.json({ error: 'ID harus diisi' }, { status: 400 });

    const targetId = Number(id);
    if (!Number.isInteger(targetId) || targetId < 1) {
      return NextResponse.json({ error: 'ID tidak valid' }, { status: 400 });
    }

    const { data: targetUser, error: targetError } = await supabase
      .from('users')
      .select('id, role')
      .eq('id', targetId)
      .single();
    if (targetError || !targetUser) {
      return NextResponse.json({ error: 'Pengguna tidak ditemukan' }, { status: 404 });
    }

    const updates = {};
    if (role) {
      if (!VALID_ROLES.has(role)) {
        return NextResponse.json({ error: 'Role tidak valid' }, { status: 400 });
      }
      const adminCount = await getAdminCount();
      if (targetUser.role === 'admin' && role !== 'admin' && adminCount <= 1) {
        return NextResponse.json({ error: 'Minimal harus ada satu admin aktif' }, { status: 400 });
      }
      if (targetId === admin.userId && role !== 'admin') {
        return NextResponse.json({ error: 'Admin tidak dapat menurunkan role akun yang sedang digunakan' }, { status: 400 });
      }
      updates.role = role;

      // Auto-resolve dusun_id ulang saat role berubah
      const dusunResolve = await resolveDusunIdForRole(role);
      if (dusunResolve.error) {
        return NextResponse.json({ error: dusunResolve.error }, { status: 400 });
      }
      updates.dusun_id = dusunResolve.value;
    }
    if (nama_lengkap) {
      const validName = validateFullName(nama_lengkap);
      if (validName.error) return NextResponse.json({ error: validName.error }, { status: 400 });
      updates.nama_lengkap = validName.value;
    }
    if (password) {
      const validPassword = validatePassword(password);
      if (validPassword.error) return NextResponse.json({ error: validPassword.error }, { status: 400 });
      updates.password_hash = await hashPassword(validPassword.value);
    }

    if (Object.keys(updates).length > 0) {
      const { error } = await supabase.from('users').update(updates).eq('id', targetId);
      if (error) throw error;

      await writeLog({
        userId: admin.userId,
        username: admin.username,
        action: 'update_user',
        tableName: 'users',
        detail: `Memperbarui data pengguna "${targetUser.username}" (${Object.keys(updates).join(', ')})`,
      });
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('[Admin Users PUT Error]:', error);
    return NextResponse.json({ error: 'Gagal memperbarui pengguna' }, { status: 500 });
  }
}
